public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }
    // Use modulus with positive k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    // Check pairs for remainders 1..k-1
    for (int r = 1; r < k; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    // Remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For even k, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch < 'a' || ch > 'z') {
            throw new IllegalArgumentException("Input string must contain only lowercase letters");
        }
        freq[ch - 'a']++;
    }
    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);
    while (remaining > 0) {
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) ('a' + i));
                freq[i]--;
                remaining--;
            }
        }
        for (int i = 25; i >= 0; i--) {
