                freq[i]--;
                remaining--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    @SuppressWarnings("unchecked")
    java.util.HashSet<Long>[] dp = (java.util.HashSet<Long>[]) new java.util.HashSet[n + 1];
    dp[0] = new java.util.HashSet<>();
    dp[0].add(0L);

    int processed = 0;
    for (int num : nums) {
        // Update dp from higher subset sizes to avoid reuse of the same element
        for (int k = Math.min(processed, n - 1); k >= 1; k--) {
            java.util.HashSet<Long> prevSet = dp[k - 1];
            if (prevSet == null || prevSet.isEmpty()) {
                continue;
            }
            java.util.HashSet<Long> currentSet = dp[k];
            if (currentSet == null) {
                currentSet = new java.util.HashSet<>();
                dp[k] = currentSet;
            }
            for (long s : prevSet) {
                currentSet.add(s + num);
            }
        }
        processed++;
    }

    for (int k = 1; k <= n - 1; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long target = (totalSum * k) / n;
        java.util.HashSet<Long> setK = dp[k];
        if (setK != null && setK.contains(target)) {
            return true;
        }
    }
    return false;
}

public int uniqueMorseRepresentations(String[] words) {
    // Morse code representation for 'a' to 'z'
    final String[] morse = {
        ".-","-...","-.-.","-..",".","..-.","--.","....","..",
        ".---","-.-",".-..","--","-.","---",".--.","--.-",".-.",
        "...","-","..-","...-",".--","-..-","-.--","--.."
    };

    if (words == null || words.length == 0) {
        return 0;
    }

    java.util.Set<String> uniqueTransforms = new java.util.HashSet<>();

    for (String word : words) {
        if (word == null) {
            continue; // skip null entries
        }
        StringBuilder transformation = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            // Consider only lowercase alphabetic characters; skip otherwise
            if (c >= 'a' && c <= 'z') {
                transformation.append(morse[c - 'a']);
            } else {
                // If encountering a non-alphabetic character, we could throw an error
                // or ignore; here we ignore the character.
            }
        }
        uniqueTransforms.add(transformation.toString());
    }

    return uniqueTransforms.size();
}

public boolean hasAllCodes(String s, int k) {
    // Validate input: s must not be null, k must be non-negative, and k should be feasible
    if (s == null || k <= 0) {
        return false;
    }

    int n = s.length();
    // If string is shorter than k, it cannot contain all codes of length k
    if (n < k) {
        return false;
    }

    int totalCodes = 1 << k; // 2^k possible binary strings of length k
    boolean[] seen = new boolean[totalCodes];
    int seenCount = 0;

    int mask = totalCodes - 1; // mask to keep only k bits
    int code = 0;

    // Build the first code from the first k characters
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    if (!seen[code]) {
        seen[code] = true;
        seenCount++;
    }

    // Slide over the rest of the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            seenCount++;
            // Early exit: all codes found
            if (seenCount == totalCodes) {
                return true;
            }
        }
    }

    return seenCount == totalCodes;
}

public int isPrefixOfWord(String sentence, String searchWord) {
