public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int n = fibs.size();
        int next = fibs.get(n - 1) + fibs.get(n - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    // Greedy subtraction
    int count = 0;
    int remaining = k;
    int i = fibs.size() - 1;
    while (remaining > 0) {
        if (fibs.get(i) <= remaining) {
            remaining -= fibs.get(i);
            count++;
        } else {
            i--;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int j = n / i;
            if (j != i) {
                large.add(j);
            }
        }
    }
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) return null;
    int n = s.length();
    char[] stack = new char[n];
    int stackSize = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (stackSize > 0 && Math.abs(c - stack[stackSize - 1]) == 32) {
            stackSize--; // remove the bad pair
        } else {
            stack[stackSize++] = c;
        }
    }
    return new String(stack, 0, stackSize);
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
