        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length must be positive");
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k out of valid range");
    }

    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - minSum; // how much more we need to add
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // max increment from 'a' to 'z' is 25
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

