public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must contain at least one element");
    }
    final int BITS = 32;
    int[] bitCounts = new int[BITS];
    for (int num : nums) {
        for (int i = 0; i < BITS; i++) {
            bitCounts[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < BITS; i++) {
        if ((bitCounts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

