    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    java.util.LinkedList<Integer> queue = new java.util.LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > high) {
            break;
        }
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        if (num <= high / 10) {
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long limit = n;
    while (limit / factor > 0) {
        int lower = (int)(limit % factor);
        int cur = (int)((limit / factor) % 10);
        int higher = (int)(limit / (factor * 10));

        if (cur == 0) {
            count += (long)higher * factor;
        } else if (cur == 1) {
            count += (long)higher * factor + lower + 1;
        } else {
            count += (long)(higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int)count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set in binary.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("num must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = 1 + (j > 0 ? horiz[i][j - 1] : 0);
                vert[i][j] = 1 + (i > 0 ? vert[i - 1][j] : 0);
                diag[i][j] = 1 + (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0);
                anti[i][j] = 1 + (i > 0 && j + 1 < n ? anti[i - 1][j + 1] : 0);
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                       Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long absValue = Math.abs((long) n);          // use long to avoid overflow for Integer.MIN_VALUE
    String digits = Long.toString(absValue);
    int length = digits.length();

    // For zero, just return "0"
    if (length == 1 && digits.charAt(0) == '0') {
        return "0";
    }

    // Determine the size of the first group of digits (1 to 3)
    int firstGroup = length % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    StringBuilder result = new StringBuilder();
    // Append the first group
    result.append(digits.substring(0, firstGroup));

    // Append the remaining groups, each preceded by a dot
    for (int i = firstGroup; i < length; i += 3) {
        result.append('.').append(digits.substring(i, i + 3));
    }

    // Add minus sign for negative numbers
    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static int squarePermutations(int[] A) {
    // Build frequency map for unique values
    java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
    for (int val : A) {
        freqMap.put(val, freqMap.getOrDefault(val, 0) + 1);
    }

    // Convert to arrays for efficient iteration
    int n = freqMap.size();
    int[] values = new int[n];
    int[] counts = new int[n];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : freqMap.entrySet()) {
        values[idx] = e.getKey();
        counts[idx] = e.getValue();
        idx++;
    }

    java.util.Map<String, Integer> memo = new java.util.HashMap<>();

    java.util.function.Function<Integer, Integer> dfs = new java.util.function.Function<Integer, Integer>() {
        @Override
        public Integer apply(Integer lastIdx) {
            // Build key for memoization
            StringBuilder keyBuilder = new StringBuilder();
            if (lastIdx == -1) {
                keyBuilder.append("nil");
            } else {
                keyBuilder.append(values[lastIdx]);
            }
            keyBuilder.append('|');
            for (int c : counts) {
                keyBuilder.append(c).append(',');
            }
            String key = keyBuilder.toString();
            if (memo.containsKey(key)) {
                return memo.get(key);
            }

            // Check if all counts zero
            boolean empty = true;
            for (int c : counts) {
                if (c > 0) {
                    empty = false;
                    break;
                }
            }
            if (empty) {
                memo.put(key, 1);
                return 1;
            }

            long total = 0;
            for (int i = 0; i < n; i++) {
                if (counts[i] == 0) continue;
                if (lastIdx != -1) {
                    int lastVal = values[lastIdx];
                    int sum = lastVal + values[i];
                    int r = (int) Math.sqrt(sum);
                    if (r * r != sum) continue;
                }
                counts[i]--;
                total += apply(i);
                counts[i]++; // backtrack
            }
            int res = (int) Math.min(total, Integer.MAX_VALUE);
            memo.put(key, res);
            return res;
        }
    };

    return dfs.apply(-1);
}

