public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("heights array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        long curHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && heights[stack.peek()] >= curHeight) {
            int h = heights[stack.pop()];
            int left = stack.isEmpty() ? -1 : stack.peek();
            long width = i - left - 1;
            long area = (long) h * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        if (i < n) {
            stack.push(i);
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return new int[0];
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    try {
        for (int sum = 0; sum <= m + n - 2; sum++) {
            if (sum % 2 == 0) {
                int i = Math.min(sum, m - 1);
                int j = sum - i;
                while (i >= 0 && j < n) {
                    result[idx++] = mat[i][j];
                    i--;
                    j++;
                }
            } else {
                int j = Math.min(sum, n - 1);
                int i = sum - j;
                while (j >= 0 && i < m) {
                    result[idx++] = mat[i][j];
                    i++;
                    j--;
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return an empty array
        return new int[0];
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    // Convert number to array of digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: find the pivot: the first index from the end where digits[i] < digits[i+1]
    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }
    // If no pivot found, no larger permutation exists
    if (pivot == -1) {
        return -1;
    }

    // Step 2: find the smallest digit larger than digits[pivot] to the right of pivot
    int successor = -1;
    for (int j = len - 1; j > pivot; j--) {
        if (digits[j] > digits[pivot]) {
            successor = j;
            break; // the rightmost such digit is the smallest greater than pivot
        }
    }

    // Step 3: swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: reverse the suffix starting at pivot+1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Reconstruct the number and check for overflow
    try {
        int result = Integer.parseInt(new String(digits));
        if (result > n) {
            return result;
        } else {
            return -1;
        }
    } catch (NumberFormatException e) {
        // In case the number exceeds integer bounds
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result; // handle invalid or non-positive lengths
    }
    char[] current = new char[n];
    buildStrobogrammatic(n, 0, n - 1, current, result);
    return result;
}

private static void buildStrobogrammatic(int n, int left, int right, char[] current, List<String> result) {
    if (left > right) {
        result.add(new String(current));
        return;
    }
    if (left == right) {
        for (char c : new char[]{'0', '1', '8'}) {
            current[left] = c;
            buildStrobogrammatic(n, left + 1, right - 1, current, result);
        }
        return;
    }
    // Pairs: (0,0), (1,1), (6,9), (8,8), (9,6)
    for (int i = 0; i < 5; i++) {
        char a = "01189".charAt(i); // left digit
        char b = "01986".charAt(i); // right digit
        if (left == 0 && a == '0' && n > 1) {
            continue; // skip leading zero for numbers > 1 digit
        }
        current[left] = a;
        current[right] = b;
        buildStrobogrammatic(n, left + 1, right - 1, current, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1 == null || p2 == null || p3 == null) {
        return false;
    }
    if (p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }
    long x1 = p1[0], y1 = p1[1];
    long x2 = p2[0], y2 = p2[1];
    long x3 = p3[0], y3 = p3[1];
    long area = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return area != 0;
}

